{
  "sop_id": "SOP-015",
  "title": "Invoice Verification (Three-Way Match)",
  "steps": [
    {"step_id": "S1", "name": "Create ticket and assign to self", "role": "Executor", "type": "intake"},
    {"step_id": "S2", "name": "Validate vendor GSTIN and PAN, check for duplicates", "role": "Executor", "type": "work"},
    {"step_id": "S3", "name": "Match invoice, PO and GRN line by line", "role": "Executor", "type": "work"},
    {"step_id": "S4", "name": "Compute GST input credit and TDS", "role": "Executor", "type": "work"},
    {"step_id": "S5", "name": "Adjust advances and other deductions", "role": "Executor", "type": "work"},
    {"step_id": "S6", "name": "Prepare payment voucher and submit", "role": "Executor", "type": "work"},
    {"step_id": "A1", "name": "Incharge verifies and approves or rejects", "role": "Incharge", "type": "approval"},
    {"step_id": "R1", "name": "Correct and resubmit on rejection", "role": "Executor", "type": "rework"},
    {"step_id": "A2", "name": "Lead approves exceptions", "role": "Lead", "type": "approval"}
  ],
  "approvals": [
    {"stage": "Incharge", "condition": "always"},
    {"stage": "Lead", "condition": "out-of-tolerance or high-value invoices"}
  ],
  "dependencies": [
    {"dep_id": "D1", "provider": "Stores", "item": "GRN or completion certificate", "parallel_group": "P1"}
  ],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
